import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumns } from '../../slots/defs/personRow';
import { peopleKey, type Person } from '../people/usePeople';
import { useRowAction } from '../people/useRowAction';

/**
 * A person's retirement: whether they are retired and from when, and the date and button to retire
 * them (a blank date is the sheet's today). Set at all, they count as retired at once, whatever the
 * date: no claim dated after it is accepted, and the list hides them unless retired people are shown.
 * A retired person can be unretired on the sheet's today: the retirement is kept as a past one, a line
 * from its date to the day unretired, and no claim dated after the from and before the to is accepted.
 */
function PersonRetire({ user, sheet, person }: { user: string; sheet: string; person: Person }) {
  const queryClient = useQueryClient();
  const [from, setFrom] = useState('');
  const retire = useMutation({
    mutationFn: (date: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/retire`, { from: date, user }),
    onSuccess: () => setFrom(''),
    onSettled: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });
  const unretire = useMutation({
    mutationFn: () =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheet)}/people/${person.id}/unretire`, { user }),
    onSettled: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheet) }),
  });
  const actionTaken = useRowAction(sheet, person.id, () => {
    retire.reset();
    unretire.reset();
  });
  return (
    <>
      <td data-testid="person-retired">{person.retired ? 'yes' : 'no'}</td>
import { createContext, useContext } from 'react';
import { asString, useSearchParam } from '../../url/useSearchParam';

const Live = createContext(false);

/** Wrap a part of the screen that always reads the sheet as it stands, whatever the as-of date: inside
 *  it `useAsOf` answers '' (the consolidated figures are live figures). */
export const LiveReads = Live.Provider;

/**
 * The date this user's screen shows the sheet as of (yyyy-mm-dd), or '' for the sheet as it stands.
 * It lives in the URL (`asof`), so it is this screen's alone. While it is set every read is of the
 * sheet as it stood at the end of that date, and every change is refused (see api/http.ts).
 */
export function useAsOf(): [string, (value: string | undefined) => void] {
  const [asOf, setAsOf] = useSearchParam('asof', asString);
  return [useContext(Live) ? '' : asOf, setAsOf];
}

/** A read's query key: the live key, or one apart from it for the sheet as of a date. It keeps the
 *  live key as its prefix, so invalidating the live key re-reads both. */
export function asOfKey<K extends readonly unknown[]>(key: K, asOf: string): K {
  return (asOf === '' ? key : [...key, { asOf }]) as unknown as K;
}

/** A read's path, asking for the sheet as of the date when one is set. */
export function asOfPath(path: string, asOf: string): string {
  return asOf === '' ? path : `${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}`;
}

